/**
 * POST /api/admin/admins/[id]/pin — New PIN for an ordinary admin (main admin only, dispatch 38).
 *
 * Response: 200 `{ admin, pin }` — `pin` generated now and in this answer
 * only, to be shown once to the main admin; stored nowhere.
 *
 * Kian's rulings of 2026-10-13: PINs are generated by Nubnb, never chosen;
 * "New PIN" — the admin's own menu, and the main admin's for an ordinary
 * admin — replaces it with another random one, shown once. Every session the
 * admin holds ends. Not for yourself (409 ADMIN_IS_YOU: your own menu's New
 * PIN), never for another main admin (409 MAIN_ADMIN_PROTECTED: only they
 * give themselves a new PIN). 404 ADMIN_NOT_FOUND. 502: it may or may not
 * have been set.
 */

import { NextRequest } from 'next/server';
import { adminRoute } from '@/app/lib/api/verify-admin';
import { apiError, apiFailure, apiSuccess, noStore } from '@/app/lib/api/safe-response';
import { ACCOUNT_REFUSALS } from '@/app/lib/admins/responses';
import { ADMIN_AUTH_NOT_CONFIGURED, getAdminPinKey } from '@/app/lib/admins/secrets';
import { refuseCrossSite } from '@/app/lib/cleaners/request-guard';
import { resetAdminPin } from '@/app/lib/firebase/server-admins';
import { isDocumentId } from '@/app/lib/firebase/server-leads';

interface RouteContext {
  params: Promise<{ id: string }>;
}

function grpcCode(err: unknown): string {
  const code = (err as { code?: unknown } | null)?.code;
  return typeof code === 'number' ? String(code) : 'unknown';
}

export const POST = adminRoute(
  async function POST(request: NextRequest, context: RouteContext, { actor }) {
    const crossSite = refuseCrossSite(request);
    if (crossSite) return crossSite;
    const pinKey = getAdminPinKey();
    if (!pinKey) return noStore(apiFailure(ADMIN_AUTH_NOT_CONFIGURED));
    const { id } = await context.params;
    if (!isDocumentId(id)) return noStore(apiError('Invalid admin ID', 400));
    try {
      const outcome = await resetAdminPin(actor, id, pinKey);
      if (outcome.kind !== 'done') return noStore(apiFailure(ACCOUNT_REFUSALS[outcome.kind]));
      console.log(`[admins] ${actor.id} gave ${id} a new PIN`);
      // The PIN travels in this answer only: shown once, stored nowhere.
      return noStore(apiSuccess({ admin: outcome.admin, pin: outcome.pin }));
    } catch (err) {
      console.error(`[admins] new PIN for ${id} failed: grpc code ${grpcCode(err)}`);
      return noStore(apiFailure({ status: 502, code: 'ADMIN_CHANGE_UNCONFIRMED', message: 'Could not confirm the new PIN was set.', hint: 'It may or may not have been. Reload the list to see.' }));
    }
  },
  { level: 'main' },
);
